        rule: '- Kişilik: Çocuğun SAĞ ve TAM doğmasıyla başlar.\n- Hak Ehliyeti: Hak ve borç sahibi olabilme yetkisidir. Pasiftir, tüm insanlarda eşittir, ana rahmine düşüldüğü anda (sağ doğmak şartıyla) kazanılır.\n- Fiil Ehliyeti: Kendi eylemleriyle hak kazanabilme ve borç altına girebilme yetkisidir. Şartları: 1) Ayırt etme gücüne sahip olmak (Mümeyyiz), 2) Ergin olmak (18 yaşını doldurmak), 3) Kısıtlı olmamak (Mahcur olmamak).\n- Hısımlık Derecesi: Doğum sayısı toplamıdır (Kardeşler 2. derece yan soy, Yeğen-Amca 3. derece yan soy, Kuzenler 4. derece yan soy).',
