        rule: '- 3 Temel İlke:\n  1. Sınıflandırma: Görevlerin niteliklerine göre meslek sınıflarına ayrılması.\n  2. Kariyer: Memurun en yüksek dereceye kadar ilerleyebilme hakkı.\n  3. Liyakat: İşe alma, terfi ve görevde yükselmede bilgi ve yeteneğin esas alınması.\n- Adaylık Süresi: En az 1 yıl, en çok 2 yıldır.\n- Yasaklar: Grev yasağı, ticaret yasağı, hediye alma yasağı, gizli bilgileri açıklama yasağı, siyasi partiye üye olma yasağı.\n- Mal Bildirimi: Sonu (0) ve (5) ile biten yıllarda en geç Şubat ayı sonuna kadar verilir.',
